class Solution {
    public int minMoves2(int[] nums) {
        java.util.Arrays.sort(nums);
        int median = nums[nums.length / 2];
        long moves = 0;
        for (int num : nums) {
            moves += Math.abs((long) num - median);
        }
        return (int) moves;
    }
}

class Solution {
    public int minMoves2(int[] nums) {
        java.util.Arrays.sort(nums);
        int left = 0;
        int right = nums.length - 1;
        long moves = 0;
        while (left < right) {
            moves += (long) nums[right] - nums[left];
            left++;
            right--;
        }
        return (int) moves;
    }
}

class Solution {
    public int minMoves2(int[] nums) {
        int median = quickSelect(nums, nums.length / 2);
        long moves = 0;
        for (int num : nums) {
            moves += Math.abs((long) num - median);
        }
        return (int) moves;
    }

    private int quickSelect(int[] nums, int k) {
        int left = 0;
        int right = nums.length - 1;
        java.util.Random random = new java.util.Random(0);
        while (left <= right) {
            int pivot = nums[left + random.nextInt(right - left + 1)];
            int lt = left;
            int i = left;
            int gt = right;
            while (i <= gt) {
                if (nums[i] < pivot) {
                    swap(nums, lt, i);
                    lt++;
                    i++;
                } else if (nums[i] > pivot) {
                    swap(nums, i, gt);
                    gt--;
                } else {
                    i++;
                }
            }
            if (k < lt) {
                right = lt - 1;
            } else if (k > gt) {
                left = gt + 1;
            } else {
                return pivot;
            }
        }
        return nums[k];
    }

    private void swap(int[] nums, int i, int j) {
        int tmp = nums[i];
        nums[i] = nums[j];
        nums[j] = tmp;
    }
}
